//! Turning AGENTS.md / CLAUDE.md / GEMINI.md into rule proposals, and the
//! text AionUi writes back once the owner hands a file over (C37, owner
//! decision 2026-11-17). Pure: file I/O is in the service.

use aionui_api_types::RULE_BODY_MAX_BYTES;

/// Files looked for in a project's workspace root, in this order.
pub const PROJECT_RULE_FILES: &[&str] = &["AGENTS.md", "CLAUDE.md", "GEMINI.md"];
/// Largest file read for an import (bytes).
pub const IMPORT_FILE_MAX_BYTES: u64 = 512 * 1024;
/// First line of every file AionUi generates; also how a generated file is
/// recognised (never imported again).
pub const GENERATED_MARKER: &str =
    "<!-- GENERATED by AionUi from the Global rules. Do not edit: change the rules in AionUi (Settings → Rules). -->";
/// The whole content of a project file AionUi manages.
pub const POINTER_LINE: &str = "Rules for this project are managed in AionUi (Settings → Rules).";

/// One proposed rule: (name, body).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProposedRule {
    pub name: String,
    pub body: String,
}

/// A file that only refers to another one (`@AGENTS.md`, an AionUi pointer
/// or a generated file) holds nothing to import.
pub fn is_pointer(content: &str) -> bool {
    let trimmed = content.trim();
    if trimmed.is_empty() || trimmed.starts_with(GENERATED_MARKER) || trimmed == POINTER_LINE {
        return true;
    }
    let lines: Vec<&str> = trimmed.lines().map(str::trim).filter(|l| !l.is_empty()).collect();
    lines.len() <= 2 && lines.iter().all(|l| l.starts_with('@') && !l.contains(' '))
}

/// Split a rules file into rules: one per `## ` section (text before the
/// first section becomes "<prefix>: Overview"; a `# ` title line is dropped
/// from it). A section over the 8 KB rule cap is split at paragraph
/// boundaries into "(part N)". Names are unique within the result.
pub fn split_into_rules(prefix: &str, content: &str) -> Vec<ProposedRule> {
    let mut sections: Vec<(String, String)> = Vec::new();
    let mut title = "Overview".to_owned();
    let mut body = String::new();
    let mut in_fence = false;
    for line in content.replace("\r\n", "\n").lines() {
        if line.trim_start().starts_with("```") {
            in_fence = !in_fence;
        }
        if !in_fence && line.starts_with("## ") {
            sections.push((std::mem::take(&mut title), std::mem::take(&mut body)));
            title = line[3..].trim().trim_end_matches('#').trim().to_owned();
            continue;
        }
        if !in_fence && sections.is_empty() && body.trim().is_empty() && line.starts_with("# ") {
            continue;
        }
        body.push_str(line);
        body.push('\n');
    }
    sections.push((title, body));

    let mut out: Vec<ProposedRule> = Vec::new();
    for (title, body) in sections {
        let body = body.trim();
        if body.is_empty() {
            continue;
        }
        let title = clean_title(&title);
        let parts = split_to_cap(body, RULE_BODY_MAX_BYTES);
        let many = parts.len() > 1;
        for (i, part) in parts.into_iter().enumerate() {
            let base = if many {
                format!("{prefix}: {title} (part {})", i + 1)
            } else {
                format!("{prefix}: {title}")
            };
            let mut name = base.clone();
            let mut n = 2;
            while out.iter().any(|r| r.name == name) {
                name = format!("{base} #{n}");
                n += 1;
            }
            out.push(ProposedRule { name, body: part });
        }
    }
    out
}

fn clean_title(title: &str) -> String {
    let cleaned: String = title
        .chars()
        .filter(|c| !c.is_control() && *c != '`' && *c != '*')
        .collect();
    let cleaned = cleaned.trim();
    let cut: String = cleaned.chars().take(60).collect();
    if cut.is_empty() { "Section".to_owned() } else { cut }
}

/// Pieces of at most `cap` bytes, cut at blank lines where possible, else at
/// line ends, else at a char boundary.
fn split_to_cap(body: &str, cap: usize) -> Vec<String> {
    if body.len() <= cap {
        return vec![body.to_owned()];
    }
    fn flush(parts: &mut Vec<String>, current: &mut String) {
        let t = current.trim();
        if !t.is_empty() {
            parts.push(t.to_owned());
        }
        current.clear();
    }
    let mut parts = Vec::new();
    let mut current = String::new();
    for paragraph in body.split("\n\n") {
        if current.len() + paragraph.len() + 2 > cap {
            flush(&mut parts, &mut current);
        }
        if paragraph.len() + 2 > cap {
            for line in paragraph.lines() {
                if current.len() + line.len() + 1 > cap {
                    flush(&mut parts, &mut current);
                }
                let mut rest = line;
                while rest.len() + 1 > cap {
                    let mut cut = cap;
                    while !rest.is_char_boundary(cut) {
                        cut -= 1;
                    }
                    parts.push(rest[..cut].to_owned());
                    rest = &rest[cut..];
                }
                current.push_str(rest);
                current.push('\n');
            }
        } else {
            current.push_str(paragraph);
            current.push_str("\n\n");
        }
    }
    flush(&mut parts, &mut current);
    parts
}

/// The global file as AionUi generates it from the Global rules
/// (name, body), in order.
pub fn render_global_file(rules: &[(String, String)]) -> String {
    let mut out = format!("{GENERATED_MARKER}\n\n# Global rules\n");
    for (name, body) in rules {
        out.push_str(&format!("\n## {name}\n\n{}\n", body.trim()));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sections_become_rules_and_the_title_is_dropped() {
        let md = "# Project\n\nIntro text.\n\n## Hard rules\n- never push\n\n```\n## not a heading\n```\n\n## Style\nTabs.\n\n## Empty\n\n";
        let rules = split_into_rules("TB", md);
        let names: Vec<&str> = rules.iter().map(|r| r.name.as_str()).collect();
        assert_eq!(names, vec!["TB: Overview", "TB: Hard rules", "TB: Style"]);
        assert_eq!(rules[0].body, "Intro text.");
        assert!(rules[1].body.contains("## not a heading"), "fenced code is not split");
        assert_eq!(rules[2].body, "Tabs.");
    }

    #[test]
    fn duplicate_headings_and_oversized_sections_stay_importable() {
        let big = format!("## Big\n{}\n\n{}\n", "a".repeat(6000), "b".repeat(6000));
        let rules = split_into_rules("G", &format!("## Same\nx\n\n## Same\ny\n\n{big}"));
        let names: Vec<&str> = rules.iter().map(|r| r.name.as_str()).collect();
        assert_eq!(
            names,
            vec!["G: Same", "G: Same #2", "G: Big (part 1)", "G: Big (part 2)"]
        );
        assert!(rules.iter().all(|r| r.body.len() <= RULE_BODY_MAX_BYTES));
        // One unbroken line over the cap is still cut, nothing is lost.
        let line = "é".repeat(RULE_BODY_MAX_BYTES);
        let parts = split_to_cap(&line, RULE_BODY_MAX_BYTES);
        assert!(parts.iter().all(|p| p.len() <= RULE_BODY_MAX_BYTES));
        assert_eq!(parts.concat().replace('\n', ""), line);
    }

    #[test]
    fn pointers_and_generated_files_are_not_imported() {
        assert!(is_pointer("@AGENTS.md\n"));
        assert!(is_pointer(""));
        assert!(is_pointer(POINTER_LINE));
        assert!(is_pointer(&render_global_file(&[("A".into(), "x".into())])));
        assert!(!is_pointer("# Rules\n\nDo things."));
        assert!(!is_pointer("@AGENTS.md\n\nAlso: be brief, always."));
    }

    #[test]
    fn generated_file_is_marked_and_ordered() {
        let text = render_global_file(&[("First".into(), "one\n".into()), ("Second".into(), "two".into())]);
        assert!(text.starts_with(GENERATED_MARKER));
        assert!(text.find("## First\n\none").unwrap() < text.find("## Second\n\ntwo").unwrap());
    }
}
